 if(argc!=2)return 1; int fd=open(argv[1],O_RDONLY); struct stat st; if(fd<0||fstat(fd,&st))return 1; size_t size=st.st_size;
 if(!size){printf("{}");return 0;} char* data=(char*)mmap(0,size,PROT_READ,MAP_PRIVATE,fd,0); if(data==MAP_FAILED)return 1;
 const int N=4; std::vector<Entry> tables[N]; std::thread threads[N];
 for(int t=0;t<N;t++)threads[t]=std::thread([&,t]{ auto&tab=tables[t];tab.resize(2048);size_t a=size*t/N,b=size*(t+1)/N;if(a)while(a<size&&data[a-1]!='\n')a++;if(b<size)while(b<size&&data[b-1]!='\n')b++;
 const char*p=data+a,*end=data+b;while(p<end){const char*s=p;uint64_t h=0;while(*p!=';')h=h*31+(unsigned char)*p++;size_t len=p-s;p++;bool neg=*p=='-';p+=neg;int v=0;while(*p!='\n'){if(*p!='.')v=v*10+*p-'0';p++;}p++;if(neg)v=-v;size_t i=h&2047;while(tab[i].count&&(tab[i].name.size()!=len||memcmp(tab[i].name.data(),s,len)))i=(i+1)&2047;auto&e=tab[i];if(!e.count)e.name.assign(s,len);e.sum+=v;e.count++;e.min=std::min(e.min,v);e.max=std::max(e.max,v);}
 });for(auto&t:threads)t.join();std::vector<Entry> all;for(auto&tab:tables)for(auto&e:tab)if(e.count)all.push_back(e);std::sort(all.begin(),all.end(),[](auto&a,auto&b){return a.name<b.name;});std::vector<Entry> out;for(auto&e:all){if(out.empty()||out.back().name!=e.name)out.push_back(e);else{auto&x=out.back();x.sum+=e.sum;x.count+=e.count;x.min=std::min(x.min,e.min);x.max=std::max(x.max,e.max);}}
 auto value=[](long long v){if(v<0){putchar('-');v=-v;}printf("%lld.%lld",v/10,v%10);};putchar('{');bool first=true;for(auto&e:out){if(!first)printf(", ");first=false;printf("%s=",e.name.c_str());value(e.min);putchar('/');long long a=llabs(e.sum),mean=(a+e.count/2)/e.count;if(e.sum<0)mean=-mean;value(mean);putchar('/');value(e.max);}putchar('}');
}

