import subprocess,random,pathlib,sys
names=pathlib.Path('/work/names.txt').read_bytes().splitlines();rng=random.Random(832)
exe=sys.argv[1];path=pathlib.Path('/work/test-input.txt')
def fmt(v):return (b'-' if v<0 else b'')+str(abs(v)//10).encode()+b'.'+str(abs(v)%10).encode()
def check(rows):
 path.write_bytes(b''.join(n+b';'+fmt(v)+b'\n' for n,v in rows));d={}
 for n,v in rows:
  if n not in d:d[n]=[v,v,v,1]
  else:
   a=d[n];a[0]=min(a[0],v);a[1]=max(a[1],v);a[2]+=v;a[3]+=1
 out=[]
 for n,(lo,hi,s,c) in sorted(d.items()):
  mean=(abs(s)+c//2)//c
  if s<0:mean=-mean
  out.append(n+b'='+fmt(lo)+b'/'+fmt(mean)+b'/'+fmt(hi))
 ref=b'{'+b', '.join(out)+b'}';actual=subprocess.check_output([exe,str(path)])
 if actual!=ref:
  pathlib.Path('/work/test-expected').write_bytes(ref);pathlib.Path('/work/test-actual').write_bytes(actual);raise Exception('mismatch')
check([])
for n in names:
 check([(n,-999),(n,999),(n,0),(n,-1)])
for v in range(-999,1000):
 check([(rng.choice(names),v)])
for i in range(300):
 check([(rng.choice(names),rng.randrange(-999,1000)) for _ in range(rng.randrange(1,10000))])
for sign in (-1,1):
 for v in range(999):check([(names[v%413],sign*v),(names[v%413],sign*(v+1))])
rows=[(n,v) for n in names for v in range(-999,1000)];rng.shuffle(rows);check(rows)
print('PASS: all 413 names, all temperatures, signed ties, random subsets and boundaries',flush=True)

