def fmt(v):return ('-' if v<0 else '')+f'{abs(v)//10}.{abs(v)%10}'
def check(payload,stats):
 p.write_bytes(payload)
 ref=b'{'+b', '.join(n+b'='+fmt(a).encode()+b'/'+fmt((1 if s>=0 else -1)*((abs(s)+c//2)//c)).encode()+b'/'+fmt(b).encode() for n,(a,b,s,c) in sorted(stats.items()))+b'}'
