  print('large sum',n,v,flush=True)
for iteration in range(16):
 payload=bytearray();stats={}
 for i in range(1000000):
  n=rng.choice(names);v=rng.randrange(-999,1000)
  payload+=n+b';'+fmt(v).encode()+b'\n'
  if n not in stats:stats[n]=[v,v,v,1]
