import pathlib,subprocess,random,sys,time,json
exe=sys.argv[1];names=pathlib.Path('/work/names.txt').read_bytes().splitlines();rng=random.Random(int(sys.argv[2]) if len(sys.argv)>2 else 967)
p=pathlib.Path('/work/stress input.txt')
def fmt(v):return ('-' if v<0 else '')+f'{abs(v)//10}.{abs(v)%10}'
def check(payload,stats):
 p.write_bytes(payload)
 ref=b'{'+b', '.join(n+b'='+fmt(a).encode()+b'/'+fmt((1 if s>=0 else -1)*((abs(s)+c//2)//c)).encode()+b'/'+fmt(b).encode() for n,(a,b,s,c) in sorted(stats.items()))+b'}'
 out=subprocess.check_output([exe,str(p)])
 if out!=ref:raise Exception('wrong output')
for n in [names[0],names[200],names[-1]]:
 for v in [-999,-501,-1,0,1,499,999]:
  line=n+b';'+fmt(v).encode()+b'\n';count=10000000
  check(line*count,{n:(v,v,v*count,count)})
  print('large sum',n,v,flush=True)
for iteration in range(16):
 payload=bytearray();stats={}
 for i in range(1000000):
  n=rng.choice(names);v=rng.randrange(-999,1000)
  payload+=n+b';'+fmt(v).encode()+b'\n'
  if n not in stats:stats[n]=[v,v,v,1]
  else:
   a=stats[n];a[0]=min(a[0],v);a[1]=max(a[1],v);a[2]+=v;a[3]+=1
 check(payload,stats);print('random million',iteration,flush=True)
 budget=json.loads(subprocess.check_output(['1brc-remaining-time']))
 if budget['remaining_seconds']<350:break
print('stress PASS',flush=True)
